const wrap = (o, k) => { if (o.__w) return; const f = o.update; o.__acc = 0; o.__n = 0; o.update = function (...x) { const t = performance.now(); const r = f.apply(this, x); o.__acc += performance.now() - t; o.__n++; return r; }; o.__w = 1; };
const T = app.trafficSystem, S = app.streetcars; wrap(T); wrap(S); if (app.transitBuses) wrap(app.transitBuses);
await sleep(7000); for (const o of [T, S, app.transitBuses]) if (o) { o.__acc = 0; o.__n = 0; }
const f = []; let last = performance.now(); const t0 = last; await new Promise((res) => { (function tick(now) { f.push(now - last); last = now; if (now - t0 < 6000) requestAnimationFrame(tick); else res(); })(performance.now()); });
f.shift(); f.sort((x, y) => x - y); const mean = f.reduce((x, y) => x + y, 0) / f.length; const ms = (o) => o ? (o.__acc / Math.max(1, o.__n)).toFixed(3) : '-';
console.log('[perf] perf-king-spadina frame ' + mean.toFixed(2) + ' ms p95 ' + f[Math.floor(f.length * 0.95)].toFixed(2) + ' ms; traffic.update ' + ms(T) + ' streetcars.update ' + ms(S) + ' transitBuses.update ' + ms(app.transitBuses) + ' ms/frame; streetcars ' + S.cars.length + ' buses on roads ' + T.buses.filter((v) => v.edge).length + ' heap ' + (performance.memory ? Math.round(performance.memory.usedJSHeapSize / 1048576) : '?') + ' MB'); })()

